def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    my = [h[0] for h in history]
    op = [h[1] for h in history]
    opp_def = sum(1 for x in op if x == 'D')
    last_my = my[-1]
    last_op = op[-1]

    if opp_def == n:
        return 'D'

    opp_streak = 0
    for x in reversed(op):
        if x == 'D':
            opp_streak += 1
        else:
            break

    recent_len = n if n < 15 else 15
    recent_def = 0
    for i in range(n - recent_len, n):
        if op[i] == 'D':
            recent_def += 1

    punished = 0
    forgiven = 0
    start = n - 31
    if start < 0:
        start = 0
    for i in range(start, n - 1):
        if my[i] == 'D' and op[i] == 'C':
            if op[i + 1] == 'D':
                punished += 1
            else:
                forgiven += 1

    if opp_def == 0:
        if forgiven >= 1:
            return 'D'
        if last_my == 'D' and last_op == 'C':
            return 'C'
        return 'D'

    if last_op == 'D':
        if opp_streak >= 3:
            return 'D'
        if recent_len >= 6 and recent_def * 2 >= recent_len:
            return 'D'
        if n >= 2 and my[-2] == 'D':
            return 'C'
        return 'D'

    if recent_len >= 6 and recent_def * 2 >= recent_len:
        return 'D'

    if punished == 0 and forgiven >= 1:
        return 'D'

    return 'C'
